B.aRE=new A.bI("major_15","\u0414\u044c\u044f\u0432\u043e\u043b","XV","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u0417\u0435\u043c\u043b\u044f","",B.atq,"\u0414\u044c\u044f\u0432\u043e\u043b \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0438 \u0442\u0435\u043d\u0435\u0432\u0443\u044e \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u0436\u0438\u0437\u043d\u0438. \u042d\u0442\u0430 \u043a\u0430\u0440\u0442\u0430 \u043c\u043e\u0436\u0435\u0442 \u043e\u0431\u043e\u0437\u043d\u0430\u0447\u0430\u0442\u044c \u043d\u0435\u0437\u0434\u043e\u0440\u043e\u0432\u044b\u0435 \u043f\u0440\u0438\u0432\u044f\u0437\u0430\u043d\u043d\u043e\u0441\u0442\u0438, \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u0438\u043b\u0438 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438, \u0432 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0432\u044b \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442\u0435 \u0441\u0435\u0431\u044f \u0432 \u043b\u043e\u0432\u0443\u0448\u043a\u0435. \u041e\u0434\u043d\u0430\u043a\u043e \u0446\u0435\u043f\u0438 \u043d\u0430 \u0448\u0435\u044f\u0445 \u0444\u0438\u0433\u0443\u0440\u043e\u043a \u043e\u0441\u043b\u0430\u0431\u043b\u0438 \u2014 \u043f\u0440\u0438 \u0436\u0435\u043b\u0430\u043d\u0438\u0438 \u043e\u043d\u0438 \u043c\u043e\u0433\u043b\u0438 \u0431\u044b \u0438\u0445 \u0441\u043d\u044f\u0442\u044c. \u0414\u044c\u044f\u0432\u043e\u043b \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0441 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c, \u0447\u0442\u043e \u043d\u0430 \u0441\u0430\u043c\u043e\u043c \u0434\u0435\u043b\u0435 \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u0435\u0442 \u0432\u0430\u0441 \u0438 \u0435\u0441\u0442\u044c \u043b\u0438 \u0443 \u0432\u0430\u0441 \u0431\u043e\u043b\u044c\u0448\u0435 \u0441\u0432\u043e\u0431\u043e\u0434\u044b, \u0447\u0435\u043c \u0432\u044b \u0434\u0443\u043c\u0430\u0435\u0442\u0435.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0414\u044c\u044f\u0432\u043e\u043b \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u043e\u0442 \u0440\u0430\u0431\u0441\u0442\u0432\u0430. \u0412\u044b \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0430\u0435\u0442\u0435\u0441\u044c \u043e\u0442 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439, \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439 \u0438 \u043d\u0435\u0437\u0434\u043e\u0440\u043e\u0432\u044b\u0445 \u043f\u0440\u0438\u0432\u044b\u0447\u0435\u043a. \u042d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0438 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0432\u0430\u0448\u0435\u0439 \u0441\u0438\u043b\u044b.","\u0420\u043e\u0433\u0430\u0442\u044b\u0439 \u043a\u0440\u044b\u043b\u0430\u0442\u044b\u0439 \u0447\u0435\u0440\u0442 \u0441\u0438\u0434\u0438\u0442 \u043d\u0430 \u043f\u043e\u043b\u0443\u043a\u0443\u0431\u0435, \u043a \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u043f\u0440\u0438\u043a\u043e\u0432\u0430\u043d\u044b \u0437\u0430 \u0448\u0435\u0438 \u0434\u0432\u0435 \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0438\u0435 \u0444\u0438\u0433\u0443\u0440\u044b. \u0426\u0435\u043f\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043e\u0441\u043b\u0430\u0431\u043b\u0435\u043d\u044b, \u0447\u0442\u043e\u0431\u044b \u0438\u0445 \u043c\u043e\u0436\u043d\u043e \u0431\u044b\u043b\u043e \u0441\u043d\u044f\u0442\u044c, \u0447\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u044c, \u0447\u0442\u043e \u0440\u0430\u0431\u0441\u0442\u0432\u043e \u0431\u044b\u043b\u043e \u043d\u0430\u043b\u043e\u0436\u0435\u043d\u043e \u0434\u043e\u0431\u0440\u043e\u0432\u043e\u043b\u044c\u043d\u043e. \u041f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u0430\u044f \u043f\u0435\u043d\u0442\u0430\u0433\u0440\u0430\u043c\u043c\u0430 \u043d\u0430\u0434 \u0433\u043e\u043b\u043e\u0432\u043e\u0439 \u0434\u044c\u044f\u0432\u043e\u043b\u0430 \u0441\u0438\u043c\u0432\u043e\u043b\u0438\u0437\u0438\u0440\u0443\u0435\u0442 \u0442\u043e\u0440\u0436\u0435\u0441\u0442\u0432\u043e \u043c\u0430\u0442\u0435\u0440\u0438\u0438 \u043d\u0430\u0434 \u0434\u0443\u0445\u043e\u043c.","\u0418\u0441\u0441\u043b\u0435\u0434\u0443\u0439\u0442\u0435, \u0447\u0442\u043e \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u0435\u0442 \u0432\u0430\u0441.","assets/tarot/m15.jpg")
B.ans=s(["\u0412\u043d\u0435\u0437\u0430\u043f\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435","\u041f\u0435\u0440\u0435\u0432\u043e\u0440\u043e\u0442","\u041e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u0435","\u0425\u0430\u043e\u0441","\u041f\u0440\u043e\u0431\u0443\u0436\u0434\u0435\u043d\u0438\u0435"],t.s)
B.aRP=new A.bI("major_16","\u0411\u0430\u0448\u043d\u044f","XVI","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u041e\u0433\u043e\u043d\u044c","\u041c\u0430\u0440\u0441",B.ans,"\u0411\u0430\u0448\u043d\u044f \u0441\u0438\u043c\u0432\u043e\u043b\u0438\u0437\u0438\u0440\u0443\u0435\u0442 \u0432\u043d\u0435\u0437\u0430\u043f\u043d\u043e\u0435, \u0434\u0440\u0430\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0438 \u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043d\u0438\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440. \u0425\u043e\u0442\u044f \u044d\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0448\u043e\u043a\u0438\u0440\u0443\u044e\u0449\u0438\u043c \u0438 \u0440\u0430\u0437\u0440\u0443\u0448\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c, \u0432 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u043c \u0438\u0442\u043e\u0433\u0435 \u044d\u0442\u043e \u043f\u0440\u0438\u0432\u043e\u0434\u0438\u0442 \u043a \u043f\u0440\u043e\u0441\u0432\u0435\u0442\u043b\u0435\u043d\u0438\u044e \u0438 \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u044e. \u041b\u043e\u0436\u043d\u044b\u0435 \u0443\u0431\u0435\u0436\u0434\u0435\u043d\u0438\u044f, \u0438\u043b\u043b\u044e\u0437\u0438\u0438 \u0438\u043b\u0438 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b, \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u043d\u0430 \u043d\u0435\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u043c \u0444\u0443\u043d\u0434\u0430\u043c\u0435\u043d\u0442\u0435, \u0440\u0430\u0437\u0440\u0443\u0448\u0430\u044e\u0442\u0441\u044f, \u0447\u0442\u043e\u0431\u044b \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u044c \u043c\u0435\u0441\u0442\u043e \u0438\u0441\u0442\u0438\u043d\u0435. \u041f\u043e\u0441\u043b\u0435 \u0411\u0430\u0448\u043d\u0438 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0417\u0432\u0435\u0437\u0434\u0430 \u2014 \u043d\u0430\u0434\u0435\u0436\u0434\u0430 \u0438 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0411\u0430\u0448\u043d\u044f \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u0432\u044b \u0441\u043e\u043f\u0440\u043e\u0442\u0438\u0432\u043b\u044f\u0435\u0442\u0435\u0441\u044c \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u043c \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u0430\u043c \u0438\u043b\u0438 \u0447\u0442\u043e \u043f\u043e\u0442\u0440\u044f\u0441\u0435\u043d\u0438\u044f \u043c\u0435\u043d\u0435\u0435 \u0434\u0440\u0430\u043c\u0430\u0442\u0438\u0447\u043d\u044b, \u0447\u0435\u043c \u043e\u043f\u0430\u0441\u0430\u043b\u0438\u0441\u044c. \u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0432\u044b \u0438\u0437\u0431\u0435\u0433\u0430\u0435\u0442\u0435 \u043a\u0440\u0438\u0437\u0438\u0441\u0430, \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0441\u0442\u043e\u044f\u0442\u044c.","\u0412 \u0431\u0430\u0448\u043d\u044e \u0443\u0434\u0430\u0440\u044f\u0435\u0442 \u043c\u043e\u043b\u043d\u0438\u044f, \u0435\u0435 \u043a\u0440\u043e\u043d\u0443 \u0441\u043d\u043e\u0441\u0438\u0442, \u0438 \u0434\u0432\u0435 \u0444\u0438\u0433\u0443\u0440\u044b \u043f\u0430\u0434\u0430\u044e\u0442 \u0433\u043e\u043b\u043e\u0432\u043e\u0439 \u0438\u0437 \u043e\u043a\u043e\u043d. \u0411\u0430\u0448\u043d\u044f \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0430 \u043d\u0430 \u0441\u043a\u0430\u043b\u0438\u0441\u0442\u043e\u043c \u0443\u0442\u0435\u0441\u0435 \u2014 \u0441\u0438\u043c\u0432\u043e\u043b \u0430\u043c\u0431\u0438\u0446\u0438\u0439, \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0445 \u043d\u0430 \u043b\u043e\u0436\u043d\u044b\u0445 \u043f\u0440\u0435\u0434\u043f\u043e\u0441\u044b\u043b\u043a\u0430\u0445. \u0423\u0434\u0430\u0440\u0438\u043b\u0430 \u043c\u043e\u043b\u043d\u0438\u044f \u0431\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0438\u0441\u0442\u0438\u043d\u044b, \u0438 \u0442\u043e, \u0447\u0442\u043e \u0431\u044b\u043b\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043e \u043d\u0430 \u0438\u043b\u043b\u044e\u0437\u0438\u044f\u0445, \u0434\u043e\u043b\u0436\u043d\u043e \u0440\u0443\u0445\u043d\u0443\u0442\u044c.","\u041e\u0442 \u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043d\u0438\u044f \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u043f\u0440\u043e\u0441\u0432\u0435\u0442\u043b\u0435\u043d\u0438\u0435.","assets/tarot/m16.jpg")
B.avb=s(["\u041d\u0430\u0434\u0435\u044f\u0442\u044c\u0441\u044f","\u0412\u0434\u043e\u0445\u043d\u043e\u0432\u0435\u043d\u0438\u0435","\u0423\u043c\u0438\u0440\u043e\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c","\u041e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435","\u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e"],t.s)
B.aRA=new A.bI("major_17","\u0417\u0432\u0435\u0437\u0434\u0430","XVII","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u0412\u043e\u0437\u0434\u0443\u0445","",B.avb,"\u0417\u0432\u0435\u0437\u0434\u0430 \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u0442 \u043d\u0430\u0434\u0435\u0436\u0434\u0443 \u0438 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043f\u043e\u0441\u043b\u0435 \u0442\u0440\u0443\u0434\u043d\u043e\u0441\u0442\u0435\u0439. \u042d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u0438\u0441\u0446\u0435\u043b\u0435\u043d\u0438\u044f, \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0438 \u0434\u0443\u0445\u043e\u0432\u043d\u043e\u0439 \u0441\u0432\u044f\u0437\u0438. \u0412\u0430\u0441 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0432\u044b\u0441\u0448\u0430\u044f \u0441\u0438\u043b\u0430, \u0438 \u0432\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u0432\u0435\u0440\u0438\u0442\u044c, \u0447\u0442\u043e \u0434\u0435\u043b\u0430 \u0438\u0434\u0443\u0442 \u0432 \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e\u043c \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0438. \u0417\u0432\u0435\u0437\u0434\u0430 \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0441 \u0432\u0435\u0440\u0438\u0442\u044c \u0432 \u0431\u0443\u0434\u0443\u0449\u0435\u0435 \u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442\u044c \u0441\u0435\u0431\u0435 \u0432\u0434\u043e\u0445\u043d\u043e\u0432\u0438\u0442\u044c\u0441\u044f \u0438 \u043e\u0431\u043d\u043e\u0432\u0438\u0442\u044c\u0441\u044f.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0417\u0432\u0435\u0437\u0434\u0430 \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043d\u0430 \u043f\u043e\u0442\u0435\u0440\u044e \u0432\u0435\u0440\u044b \u0438\u043b\u0438 \u043d\u0430\u0434\u0435\u0436\u0434\u044b. \u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0432\u044b \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442\u0435 \u0441\u0435\u0431\u044f \u043e\u0442\u043e\u0440\u0432\u0430\u043d\u043d\u044b\u043c \u043e\u0442 \u0441\u0432\u043e\u0435\u0433\u043e \u0434\u0443\u0445\u043e\u0432\u043d\u043e\u0433\u043e \u043f\u0443\u0442\u0438 \u0438\u043b\u0438 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442\u0435 \u0443\u0432\u0438\u0434\u0435\u0442\u044c \u0441\u0432\u0435\u0442 \u0432 \u043a\u043e\u043d\u0446\u0435 \u0442\u0443\u043d\u043d\u0435\u043b\u044f. \u0412\u0430\u0436\u043d\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0441\u0432\u044f\u0437\u044c \u0441 \u0442\u0435\u043c, \u0447\u0442\u043e \u0432\u0430\u0441 \u0432\u0434\u043e\u0445\u043d\u043e\u0432\u043b\u044f\u0435\u0442.","\u041e\u0431\u043d\u0430\u0436\u0435\u043d\u043d\u0430\u044f \u0436\u0435\u043d\u0449\u0438\u043d\u0430 \u0441\u0442\u043e\u0438\u0442 \u043d\u0430 \u043a\u043e\u043b\u0435\u043d\u044f\u0445 \u0443 \u043b\u0443\u0436\u0438 \u0441 \u0432\u043e\u0434\u043e\u0439 \u0438 \u043b\u044c\u0435\u0442 \u0432\u043e\u0434\u0443 \u0438\u0437 \u0434\u0432\u0443\u0445 \u043a\u0443\u0432\u0448\u0438\u043d\u043e\u0432 \u2014 \u043e\u0434\u043d\u043e\u0433\u043e \u043d\u0430 \u0437\u0435\u043c\u043b\u044e, \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0432 \u0431\u0430\u0441\u0441\u0435\u0439\u043d. \u041d\u0430\u0434 \u043d\u0435\u0439 \u043d\u0430 \u043d\u0435\u0431\u0435 \u0441\u0438\u044f\u044e\u0442 \u0432\u043e\u0441\u0435\u043c\u044c \u0437\u0432\u0435\u0437\u0434, \u0441\u0430\u043c\u0430\u044f \u0431\u043e\u043b\u044c\u0448\u0430\u044f \u0438\u0437 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u2014 \u0432\u043e\u0441\u044c\u043c\u0438\u043a\u043e\u043d\u0435\u0447\u043d\u0430\u044f. \u041d\u0435\u043f\u043e\u0434\u0430\u043b\u0435\u043a\u0443 \u043d\u0430 \u0434\u0435\u0440\u0435\u0432\u0435 \u0441\u0438\u0434\u0438\u0442 \u0438\u0431\u0438\u0441. \u0421\u0446\u0435\u043d\u0430 \u0438\u0437\u043b\u0443\u0447\u0430\u0435\u0442 \u0441\u043f\u043e\u043a\u043e\u0439\u0441\u0442\u0432\u0438\u0435 \u0438 \u043d\u0430\u0434\u0435\u0436\u0434\u0443.","\u0412\u0435\u0440\u044c\u0442\u0435 \u2013 \u0432\u0430\u0448\u0430 \u0437\u0432\u0435\u0437\u0434\u0430 \u0432\u043e\u0441\u0445\u043e\u0434\u0438\u0442.","assets/tarot/m17.jpg")
